# owner: platform
from typing import List

from hourglass.schedule import worker_minutes
from hourglass.errors import ProjectError
from collections import Counter


def _validate(shifts: List) -> None:
    if not shifts:
        raise ProjectError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("shift has no worker")


def _line(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} h"


def timesheet_lines(shifts: List) -> List[str]:
    """One line per worker, busiest first."""
    _validate(shifts)
    counts = Counter(shift.worker for shift in shifts)
    totals = worker_minutes(shifts)
    order = sorted(
        totals, key=lambda name: (-totals[name], name)
    )
    return [
        _line(name, counts[name], totals[name])
        for name in order
    ]

