# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def _shift(worker, begin, stop):
    return Shift(worker, "mon", Span(begin, stop))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            _shift("Ana", 480, 540),
            _shift("Brisa", 480, 720),
            _shift("Ana", 600, 660),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 1 shifts, 4.0 h",
                "Ana: 2 shifts, 2.0 h",
            ],
        )

    def test_empty(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([_shift("  ", 480, 540)])
